def f(I):
    H,W=len(I),len(I[0]); O=[r[:] for r in I]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if I[i][j]==5 and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and I[x][y]==5 and not seen[x][y]:
                            seen[x][y]=True;st.append((x,y))
                rs=[a for a,b in cells];cs=[b for a,b in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # interior fill
                for a in range(r0+1,r1):
                    for b in range(c0+1,c1):
                        if O[a][b]!=5: O[a][b]=2
                # gap on top row within interior span
                inter=set(range(c0+1,c1))
                gaps=[b for b in inter if I[r0][b]==0]
                if gaps:
                    g=gaps[0]
                    # far wall: wall col farther from gap
                    far = c0 if g>c0 else c1
                    step = -1 if far<c0 else 1  # move from gap toward far wall side
                    # determine direction: if gap closer to c0 side? use sign(gap - (c0+c1)/2) flipped?
                    # far wall col: if gap is on left half, far wall is right wall c1 -> direction +1; else -1
                    dirn = 1 if g<(c0+c1)/2 else -1
                    b=g
                    while 0<=b<W:
                        if O[r0-1][b]==5: break
                        O[r0-1][b]=2
                        b+=dirn
    return O

