def f(I):
    O=[r[:] for r in I]; H,W=len(I),len(I[0])
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if I[i][j]==5 and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and I[x][y]==5 and not seen[x][y]:
                            seen[x][y]=True;st.append((x,y))
                rs=[a for a,b in cells];cs=[b for a,b in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # skip if no gap or already enclosed
                inter=list(range(c0+1,c1))
                if r0==0 or not any(I[r0][b]==0 for b in inter): continue
                g=[b for b in inter if I[r0][b]==0]
                lw = [b for b in range(c0) if I[r0][b]==5]
                rw = [b for b in range(c1+1,W) if I[r0][b]==5]
                L=lw[-1] if lw else -1
                R=rw[0] if rw else W
                # gap nearest wall decides direction: distance from gap to each outside 5
                dL=min(abs(g[0]-L), abs(g[-1]-L)) if lw else 99
                dR=min(abs(b-R) for b in g) if rw else 99
                # tie-break by which end of gap is closer: shoot AWAY from nearer wall
                if L!=None and (dL < dR or (dL==dR and abs(g[0]-L)<=abs(g[-1]-R))):
                    rng=range(0,g[0])   # leftward, stop before wall column L
                else:
                    rng=range(g[-1]+1,W)  # rightward
                for b in rng:
                    if O[r0-1][b]==5: break
                    O[r0-1][b]=2
                for gg in g: O[r0][gg]=2
    return O
