    # diff cells
    D=[(i,j,I[i][j],O[i][j]) for i in range(H) for j in range(W) if I[i][j]!=O[i][j]]
    print('diff:',D)

def f(I):
    O=[r[:] for r in I]; H,W=len(I),len(I[0])
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if I[i][j]==5 and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and I[x][y]==5 and not seen[x][y]:
                            seen[x][y]=True;st.append((x,y))
                rs=[a for a,b in cells];cs=[b for a,b in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                g=[b for b in range(c0+1,c1) if I[r0][b]==0]
                if not g or r0==0: continue
                # interior fill + gap
                for b in range(c0+1,c1):
                    if I[r0+1][b]!=5: O[r0+1][b]=2
                for a in range(r0+1,r1):
                    for b in range(c0+1,c1):
                        if O[a][b]!=5: O[a][b]=2
                for gg in g: O[r0][gg]=2
                # ray: toward longer flank run; tie -> left
                L = sum(1 for b in range(c0,g[0]+1) if I[r0][b]==5)
                R = sum(1 for b in range(g[-1],c1+1) if I[r0][b]==5)
                rng = range(g[0],-1,-1) if L>=R else range(g[-1],W)
                for b in rng:
                    if I[r0-1][b]==5: break
                    O[r0-1][b]=2
    return O
for n in (1,2,3):
    print(n, f(G[f'Demo pair {n} input'])==G[f'Demo pair {n} output'])
